import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] dep = new long[n], ret = new long[n];
        for (int i = 0; i < n; i++) dep[i] = nextLong();
        for (int i = 0; i < n; i++) ret[i] = nextLong();
        // Scan departure days right to left, keeping the cheapest strictly later return.
        long bestReturn = ret[n - 1], answer = dep[n - 2] + bestReturn;
        for (int i = n - 2; i >= 0; i--) {
            bestReturn = Math.min(bestReturn, ret[i + 1]);
            answer = Math.min(answer, dep[i] + bestReturn);
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	dep := make([]int64, n)
	ret := make([]int64, n)
	for i := range dep {
		dep[i] = nextInt()
	}
	for i := range ret {
		ret[i] = nextInt()
	}
	// Scan departure days right to left, keeping the cheapest strictly later return.
	bestReturn := ret[n-1]
	answer := dep[n-2] + bestReturn
	for i := n - 2; i >= 0; i-- {
		bestReturn = min(bestReturn, ret[i+1])
		answer = min(answer, dep[i]+bestReturn)
	}
	fmt.Println(answer)
}
